import {RAD,clamp,lerp,V} from 'https://spagnuolocarmine.github.io/assets/tools/vento/dist/constants.js';
import {rigDimensions,selectedArea} from 'https://spagnuolocarmine.github.io/assets/tools/vento/dist/orc-sails.js';
import {sailFlow} from 'https://spagnuolocarmine.github.io/assets/tools/vento/dist/sail-flow.js';
import {boatScale,boatProfile,beamRatio,headsailScale,isCertificateBoat} from 'https://spagnuolocarmine.github.io/assets/tools/vento/dist/boats.js';
import {standingRigLayout} from 'https://spagnuolocarmine.github.io/assets/tools/vento/dist/rig-layout.js';
import {sailDesign,measuredArea} from 'https://spagnuolocarmine.github.io/assets/tools/vento/dist/sail-measures.js';
export const windSide=s=>-(Math.sign(Math.sin(s.windAngle*RAD))||1);
const responseCache=new WeakMap();
export function rigResponse(s){const r=s.controls.rig,md=sailDesign('main',s),gd=sailDesign('genoa',s),ma=isCertificateBoat(s)&&!md.exploratory?boatProfile(s).areas.main:measuredArea('main',md),ga=isCertificateBoat(s)&&!gd.exploratory?boatProfile(s).areas.genoa:measuredArea('genoa',gd),fa=s.foresail==='genoa'?ga*headsailScale(s):selectedArea(s.foresail,s),key=[r.backstay,r.forestay,r.shrouds,s.windSpeed,s.windAngle,s.boatSpeed,s.genoaSize,s.main,s.foresail,fa,boatProfile(s).id,boatScale(s),md.P,gd.HLU,ma,ga],cached=responseCache.get(s);if(cached&&key.every((x,i)=>x===cached.key[i]))return cached.value;const k=boatScale(s),rig=rigDimensions(s),L=rig.ISP*k,flow=sailFlow(s),aws=flow.aws,q=flow.q,wx=s.windSpeed*Math.sin(s.windAngle*RAD),headsailArea=fa,mainArea=s.main?ma:0;
 const sideLoad=q*(mainArea+headsailArea)*.75*(aws>.001?Math.abs(wx)/aws:0),backstayN=(1000+110*r.backstay)*k*k,forestayN=(3000+120*r.forestay)*k*k+.40*backstayN,shroudN=(5000+150*r.shrouds)*k*k,lateralStiffness=(6000+32000*r.shrouds/100)*k,tipDeflection=.65*Math.tanh(sideLoad/lateralStiffness/k/.65),bendingMoment=.30*backstayN+.04*shroudN-.015*forestayN,prebend=.025+bendingMoment*L*L/(8*450000*k**4),rake=.02+backstayN/(90000*k*k)-(forestayN-.4*backstayN)/(500000*k*k),forestayLoad=q*(s.foresail==='genoa'?headsailArea:0)*.75,sag=.008+.642*Math.tanh(forestayLoad*Math.hypot(L,rig.J*k)/(8*forestayN)/k/.642);
 const value={backstayN,forestayN,shroudN,sideLoad,tipDeflection,prebend,rake,sag,awa:flow.awa};responseCache.set(s,{key,value});return value;}
const mastCache=new WeakMap();
export function mastPoint(v,s){const r=rigResponse(s);let cached=mastCache.get(s);if(!cached||cached.response!==r){cached={response:r,points:new Map()};mastCache.set(s,cached);}if(cached.points.has(v))return [...cached.points.get(v)];const rig=rigDimensions(s),point=[windSide(s)*r.tipDeflection*v**1.8,1.2+rig.ISP*v,rig.mastZ+r.prebend*4*v*(1-v)-r.rake*v];cached.points.set(v,point);return [...point];}
export function forestayPoint(v,s){const rig=rigDimensions(s),top=mastPoint(rig.foreFraction,s),base=[0,1,rig.mastZ+rig.J],response=rigResponse(s),axis=V.unit(V.sub(top,base)),wind=[-Math.sin(s.windAngle*RAD),0,-Math.cos(s.windAngle*RAD)];let direction=V.sub(wind,V.mul(axis,V.dot(wind,axis)));direction=V.unit(direction);return base.map((x,i)=>lerp(x,top[i],v)+direction[i]*response.sag*4*v*(1-v));}
export function spreaderEndpoints(s,side,h){const layout=standingRigLayout(s),a=mastPoint(h,s),width=h>.6?layout.upperSpreader:layout.lowerSpreader;return[a,[a[0]+side*width,a[1]+.08,a[2]-(h>.6?layout.upperSweep:layout.lowerSweep)]];}
export function shroudPath(s,side,N=32){const layout=standingRigLayout(s),stations=[0,.42,.71,1],top=mastPoint(1,s),a=spreaderEndpoints(s,side,.42)[1],b=spreaderEndpoints(s,side,.71)[1],anchors=[[side*layout.chainplateX,.91,layout.shroudZ],a,b,top];return Array.from({length:N+1},(_,i)=>{const v=i/N;let k=1;while(k<3&&v>stations[k])k++;const f=(v-stations[k-1])/(stations[k]-stations[k-1]),slack=(1-s.controls.rig.shrouds/100)*.10*Math.sin(Math.PI*f),p=anchors[k-1].map((x,j)=>lerp(x,anchors[k][j],f));p[0]+=side*slack;p[1]-=slack*.25;return p;});}
export function shroudAtHeight(s,side,y){const points=shroudPath(s,side,24);let k=1;while(k<points.length-1&&points[k][1]<y)k++;const a=points[k-1],b=points[k],f=clamp((y-a[1])/(b[1]-a[1]));return a.map((x,i)=>lerp(x,b[i],f));}

const luffCache=new WeakMap();
export function headsailLuffPoint(v,s){const response=rigResponse(s),length=sailDesign('genoa',s).HLU/boatScale(s);let cached=luffCache.get(s);if(!cached||cached.response!==response||cached.length!==length){const points=Array.from({length:49},(_,i)=>forestayPoint(i/48,s)),arcs=[0];for(let i=1;i<points.length;i++)arcs.push(arcs.at(-1)+V.length(V.sub(points[i],points[i-1])));cached={response,length,arcs,total:arcs.at(-1),samples:new Map()};luffCache.set(s,cached);}if(cached.samples.has(v))return [...cached.samples.get(v)];const target=clamp(v)*(sailDesign('genoa',s).exploratory?length:Math.min(length,cached.total));if(target>cached.total){const top=forestayPoint(1,s),axis=V.unit(V.sub(top,forestayPoint(.98,s))),point=V.add(top,V.mul(axis,target-cached.total));cached.samples.set(v,point);return [...point];}let a=0,b=48;while(b-a>1){const i=(a+b)>>1;if(cached.arcs[i]<target)a=i;else b=i;}const f=(target-cached.arcs[a])/Math.max(1e-12,cached.arcs[b]-cached.arcs[a]);const point=forestayPoint((a+f)/48,s);cached.samples.set(v,point);return [...point];}
